style.css:
@-moz-document domain("docs.dynatrace.com") {
/* Fundo principal e texto padrão */
    body, html, main, article {
        background-color: #121212 !important;
        color: #e0e0e0 !important;
    }

    /* Cabeçalhos */
    h1, h2, h3, h4, h5, h6 {
        color: #ffffff !important;
    }

    /* Links */
    a {
        color: #64a0ff !important;
        text-decoration: none !important;
    }
    
    a:hover {
        color: #8ebcff !important;
        text-decoration: underline !important;
    }

    /* Barra de Navegação (Top bar), Menus Laterais e Rodapé */
    header, nav, aside, footer, .sidebar, .toc {
        background-color: #1a1a1a !important;
        border-color: #333333 !important;
        color: #d1d1d1 !important;
    }

    /* Blocos de Código (Code blocks e inline code) */
    pre, code, kbd, samp {
        background-color: #2b2b2b !important;
        color: #f8f8f2 !important;
        border: 1px solid #404040 !important;
        text-shadow: none !important;
    }

    /* Tabelas */
    table, th, td {
        border-color: #404040 !important;
        background-color: #1e1e1e !important;
        color: #e0e0e0 !important;
    }
    
    th {
        background-color: #2a2a2a !important;
    }

    /* Botões e Caixas de Busca */
    button, input, select, textarea {
        background-color: #333333 !important;
        color: #ffffff !important;
        border: 1px solid #555555 !important;
    }

    /* Ajuste para itens de menu e sumário (TOC) */
    ul, li {
        color: #d1d1d1 !important;
    }
    
    /* Destaques (Callouts/Alertas comuns na doc) */
    .alert, .admonition, blockquote {
        background-color: #222222 !important;
        border-left: 4px solid #64a0ff !important;
        color: #e0e0e0 !important;
    }
    
    /* Remove sombras e ajusta bordas excessivamente claras */
    * {
        box-shadow: none !important;
    }
}
